`timescale 1ns/1ps
// HA1 full-die boundary bench: 32 SMs of the V4.1 HBM die at the floorplan's wire distances, 1.2 GHz SS
// registered stages (results/floorplan/hbm_gpu/v41_hbm_die.json, 504 um per stage; the stage table is
// generated by tools/hbm_accel/run_ha1_die.py into ha1_die_stages.svh).  Each SM finishes its op a random
// time after it is released, then arrives (barrier sense) and sends its last row block toward the x hub.
// Variants (VARIANT):
//   0 tree        ablation: ot_gpu_barrier_node quadrant/root tree, release broadcast; the hub broadcasts the
//                 last block (XBEATS beats, pipelined with the release) once the root has every arrival;
//                 an SM may start when released AND its x block has landed.
//   1 txcount_a2a R1b as priced: no root release; every SM's sense goes point-to-point (per-pair floorplan
//                 stages) to every SM's ot_hbm_txcount_arrival counter.  Sync only (no x data).
//   2 tree_sync   variant 0 without x data (the 62-cycle measured barrier).
//   3 txcount_x   tx-count on the data: no barrier at all; the hub forwards the last block the cycle it lands,
//                 each SM counts the x beats it receives (tx bytes) and starts when the count is complete.
// Measured per boundary: last SM finish -> every SM may start.
module tb_txcount_die;
    parameter integer VARIANT = 0, NBAR = 200, WMAX = 300, XBEATS = 16, SEED = 5;
    localparam integer N = 32, K1 = 8, K2 = 4;
    `include "ha1_die_stages.svh"   // D_LEAF, D_TRUNK, D_UP (SM->hub data), D_DN (hub->SM data), STG[N*N] pair stages
    reg clk = 0, rst_n = 0;
    always #0.5 clk = ~clk;
    reg  [N-1:0] arrive = 0;          // barrier senses
    reg  [N-1:0] blk = 0;             // last-block toggles toward the hub
    wire [N-1:0] rel_sm;
    wire root_gate;                   // tree: the root's arrival sense (the hub's x broadcast waits for it)
    genvar s, q, t;
    // ---------------- barrier network
    generate if (VARIANT == 0 || VARIANT == 2) begin : g_tree
        wire [N-1:0] arr_q, q_rel;
        wire [K2-1:0] q_up, q_up_far, q_rel_in, root_rel;
        wire root_up;
        for (s = 0; s < N; s = s + 1) begin : g_sm
            ot_gpu_barrier_link #(.D(D_LEAF)) u_a (.clk(clk), .rst_n(rst_n), .d(arrive[s]), .q(arr_q[s]));
            ot_gpu_barrier_link #(.D(D_LEAF)) u_r (.clk(clk), .rst_n(rst_n), .d(q_rel[s]), .q(rel_sm[s]));
        end
        for (q = 0; q < K2; q = q + 1) begin : g_q
            ot_gpu_barrier_node #(.K(K1)) u_n (.clk(clk), .rst_n(rst_n), .arr(arr_q[q*K1 +: K1]), .up(q_up[q]),
                                               .rel_in(q_rel_in[q]), .rel(q_rel[q*K1 +: K1]));
            ot_gpu_barrier_link #(.D(D_TRUNK)) u_a (.clk(clk), .rst_n(rst_n), .d(q_up[q]), .q(q_up_far[q]));
            ot_gpu_barrier_link #(.D(D_TRUNK)) u_r (.clk(clk), .rst_n(rst_n), .d(root_rel[q]), .q(q_rel_in[q]));
        end
        ot_gpu_barrier_node #(.K(K2)) u_root (.clk(clk), .rst_n(rst_n), .arr(q_up_far), .up(root_up),
                                              .rel_in(root_up), .rel(root_rel));
        assign root_gate = root_up;
    end else if (VARIANT == 1) begin : g_a2a
        for (t = 0; t < N; t = t + 1) begin : g_cons
            wire [N-1:0] arr_t;
            for (s = 0; s < N; s = s + 1) begin : g_src
                ot_gpu_barrier_link #(.D(STG[(s*N + t)*8 +: 8])) u_l (.clk(clk), .rst_n(rst_n), .d(arrive[s]), .q(arr_t[s]));
            end
            ot_hbm_txcount_arrival #(.ENABLE(1), .K(N)) u_c (.clk(clk), .rst_n(rst_n), .arr(arr_t), .rel(rel_sm[t]));
        end
        assign root_gate = 1'b0;
    end else begin : g_none
        assign rel_sm = {N{1'b0}};
        assign root_gate = 1'b0;
    end endgenerate
    // ---------------- x data: last blocks up to the hub, beats down to every SM, tx (beat) counters
    wire [N-1:0] xdone;               // per SM: this boundary's x beats all landed (toggle)
    generate if (VARIANT == 0 || VARIANT == 3) begin : g_x
        wire [N-1:0] blk_h;
        for (s = 0; s < N; s = s + 1) begin : g_up
            ot_gpu_barrier_link #(.D(D_UP)) u_u (.clk(clk), .rst_n(rst_n), .d(blk[s]), .q(blk_h[s]));
        end
        // hub: tx-count of blocks landed this boundary; when complete (and, for the tree, the root fired),
        // it streams the last block's XBEATS beats into the broadcast tree (registered at the hub).
        reg [5:0] nb; reg hsense; reg [N-1:0] blk_seen; reg [7:0] beats; reg beat;
        integer i, c;
        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin nb <= 0; hsense <= 1'b0; blk_seen <= 0; beats <= 0; beat <= 1'b0; end
            else begin
                c = 0;
                for (i = 0; i < N; i = i + 1) if (blk_h[i] != blk_seen[i]) c = c + 1;
                blk_seen <= blk_h;
                beat <= 1'b0;
                if (beats != 0) begin beat <= 1'b1; beats <= beats - 1'b1; end
                else if (nb + c == N && (VARIANT == 3 || root_gate == ~hsense)) begin
                    nb <= 0; hsense <= ~hsense; beats <= XBEATS - 1; beat <= 1'b1;
                end else nb <= nb + c;
            end
        end
        for (s = 0; s < N; s = s + 1) begin : g_dn
            wire bq;
            ot_gpu_barrier_link #(.D(D_DN)) u_d (.clk(clk), .rst_n(rst_n), .d(beat), .q(bq));
            reg [7:0] cnt; reg xs;
            always @(posedge clk or negedge rst_n)
                if (!rst_n) begin cnt <= 0; xs <= 1'b0; end
                else if (bq) begin
                    if (cnt == XBEATS - 1) begin cnt <= 0; xs <= ~xs; end else cnt <= cnt + 1'b1;
                end
            assign xdone[s] = xs;
        end
    end else begin : g_nx
        assign xdone = {N{1'b0}};
    end endgenerate
    // ---------------- SMs
    integer cyc = 0, b, i, t_last, lat, lat_min = 1 << 30, lat_max = 0, lat_sum = 0, errs = 0, seed = SEED;
    integer wdone [0:N-1];
    reg sense = 0;
    wire use_rel = (VARIANT != 3);
    wire use_x = (VARIANT == 0 || VARIANT == 3);
    reg [N-1:0] go;
    always @* for (i = 0; i < N; i = i + 1)
        go[i] = (!use_rel || rel_sm[i] == sense) && (!use_x || xdone[i] == sense);
    always @(posedge clk) cyc <= cyc + 1;
    initial begin
        repeat (4) @(posedge clk);
        rst_n = 1;
        for (b = 0; b < NBAR; b = b + 1) begin
            sense = ~sense;
            for (i = 0; i < N; i = i + 1) wdone[i] = cyc + 1 + ($urandom(seed) % WMAX);
            while (arrive != {N{sense}}) begin
                @(negedge clk);
                for (i = 0; i < N; i = i + 1) if (cyc >= wdone[i] && arrive[i] != sense) begin
                    arrive[i] = sense; blk[i] = sense;
                end
                if (go != 0) errs = errs + 1;       // nobody may start before the last SM finished
            end
            t_last = cyc;
            while (go != {N{1'b1}}) @(negedge clk);
            lat = cyc - t_last;
            lat_sum = lat_sum + lat;
            if (lat < lat_min) lat_min = lat;
            if (lat > lat_max) lat_max = lat;
        end
        $display("HA1_DIE variant=%0d n=%0d d_leaf=%0d d_trunk=%0d d_up=%0d d_dn=%0d xbeats=%0d barriers=%0d last_finish_to_all_start_min=%0d max=%0d mean_x100=%0d early_start_errors=%0d",
                 VARIANT, N, D_LEAF, D_TRUNK, D_UP, D_DN, XBEATS, NBAR, lat_min, lat_max, (100 * lat_sum) / NBAR, errs);
        $finish;
    end
endmodule
